<?php
require_once __DIR__.'/../../config/config.php';require_roles(['ADMIN','HR']);$pdo=db();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT d.*,e.first_name,e.last_name,e.employee_number,t.name type_name FROM document_drafts d JOIN employees e ON e.id=d.employee_id JOIN document_types t ON t.id=d.document_type_id WHERE d.id=?');$q->execute([$id]);$draft=$q->fetch();if(!$draft){http_response_code(404);exit('Draft not found.');}$error=null;$transitions=['DRAFT'=>['FOR_REVIEW'],'FOR_REVIEW'=>['APPROVED','DRAFT'],'APPROVED'=>['FINALIZED'],'FINALIZED'=>['ARCHIVED'],'ARCHIVED'=>[]];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$target=['submit'=>'FOR_REVIEW','approve'=>'APPROVED','reject'=>'DRAFT','finalize'=>'FINALIZED','archive'=>'ARCHIVED'][$action]??'';if(!in_array($target,$transitions[$draft['status']]??[],true))$error='Invalid document status transition.';elseif($target==='DRAFT'&&!trim((string)$_POST['reason']))$error='Rejection requires a reason.';else{$pdo->beginTransaction();try{$fields=['status=?'];$params=[$target];if($target==='DRAFT'){$fields[]='rejection_reason=?';$params[]=$_POST['reason'];}$fields[]='reviewed_by=?';$params[]=$_SESSION['user_id'];$fields[]='reviewed_at=NOW()';$params[]=$id;$pdo->prepare('UPDATE document_drafts SET '.implode(',',$fields).' WHERE id=?')->execute($params);$pdo->prepare('INSERT INTO document_reviews (draft_id,action,reason,performed_by) VALUES (?,?,?,?)')->execute([$id,$action==='submit'?'SUBMITTED':($target==='DRAFT'?'REJECTED':$target),post_value('reason'),$_SESSION['user_id']]);audit('DRAFT_'.strtoupper($action),'document_drafts',$id);$pdo->commit();flash('success','Draft status updated.');redirect('draft.php?id='.$id);}catch(Throwable $exception){$pdo->rollBack();$error='The status update was rolled back.';}}}$versions=$pdo->prepare('SELECT v.*,u.username FROM document_versions v LEFT JOIN users u ON u.id=v.created_by WHERE v.draft_id=? ORDER BY v.version_number DESC');$versions->execute([$id]);$versions=$versions->fetchAll();$pageTitle='Document draft';require __DIR__.'/../../includes/header.php';?><div class="mb-7"><a href="records.php?employee_id=<?=$draft['employee_id']?>" class="text-sm font-bold text-teal-700">← Employee records</a><h1 class="font-display text-3xl font-bold mt-2"><?=e($draft['title'])?></h1><p class="text-sm text-slate-500"><?=e($draft['employee_number'].' · '.$draft['first_name'].' '.$draft['last_name'])?> · <?=e($draft['status'])?></p></div><?php if($error):?><div class="mb-5 rounded-lg bg-red-50 p-3 text-sm text-red-700"><?=e($error)?></div><?php endif;?><div class="grid xl:grid-cols-[1fr_320px] gap-6"><section class="bg-white border rounded-xl p-6"><form method="post"><?= csrf_field() ?><textarea name="content" rows="18" class="field !mt-0" readonly><?=e($draft['content'])?></textarea><p class="text-xs text-slate-500 mt-3">Meaningful version editing is reserved for the next editor iteration; every generated draft has an immutable initial version.</p></form></section><aside class="bg-white border rounded-xl p-6"><h2 class="font-display text-xl font-bold">Workflow</h2><div class="space-y-2 mt-4"><?php foreach($transitions[$draft['status']]??[] as $next):?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="<?=strtolower($next==='FOR_REVIEW'?'submit':($next==='APPROVED'?'approve':($next==='FINALIZED'?'finalize':($next==='ARCHIVED'?'archive':'reject'))))?>"><input name="reason" placeholder="Reason if rejecting" class="field !mt-0 mb-2"><button class="w-full rounded-lg bg-teal-700 px-4 py-3 text-sm font-bold text-white">Move to <?=e($next)?></button></form><?php endforeach;?><?php if(!$transitions[$draft['status']]):?><p class="text-sm text-slate-500">This draft is archived.</p><?php endif;?></div><h2 class="font-display text-xl font-bold mt-8">Versions</h2><?php foreach($versions as $version):?><p class="border-b py-3 text-sm"><b>Version <?=e($version['version_number'])?></b><span class="block text-xs text-slate-500"><?=e($version['change_description']??'')?></span></p><?php endforeach;?></aside></div><?php require __DIR__.'/../../includes/footer.php';